function climbStairs(n, memo = new Map()) {
  if (n <= 2) return n
  if (memo.has(n)) return memo.get(n)       // solved before: reuse it
  const result = climbStairs(n - 1, memo) + climbStairs(n - 2, memo)
  memo.set(n, result)                       // first time: save it
  return result
}

