def coin_change(coins, amount):
    INF = float("inf")
    dp = [0] + [INF] * amount           # dp[a] = fewest coins for amount a
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1    # last coin c, best for the rest
    return dp[amount] if dp[amount] != INF else -1

print(coin_change([1, 3, 4], 6))   # 2   (3 + 3; greedy takes 4 + 1 + 1)
print(coin_change([2], 3))         # -1  (odd amounts are impossible)

def length_of_lis(nums):
    if not nums:
        return 0
    dp = [1] * len(nums)              # dp[i] = LIS ending exactly at i
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)                    # best ending anywhere

print(length_of_lis([10, 9, 2, 5, 3, 7, 101, 18]))   # 4

def unique_paths(m, n):
    row = [1] * n                   # first row: one path to each cell
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]    # from above (old row[c]) + from the left
    return row[-1]

print(unique_paths(3, 7))   # 28

def lcs(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]   # row/col 0: empty prefix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1          # use both
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])  # drop one
    return dp[m][n]

print(lcs("abcde", "ace"))   # 3

